/* cppi::23da796f33aa058594badbc4ddde92ecfe9705934033dcbcf0f1582ca946cb88 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-28' and end_date = '2025-04-28')
and start_date = '2025-04-28' and end_date = '2025-04-28'

